shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/bin/bat/app.rs b/src/bin/bat/app.rs
--- a/src/bin/bat/app.rs
+++ b/src/bin/bat/app.rs
@@ -442,3 +442,53 @@
         Ok(styled_components)
     }
 }
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn paging_with_plain() {
+        for interactive_output in [false, true] {
+            for paging in [None, Some("auto"), Some("never"), Some("always")] {
+                for plain in [
+                    &['p'][..],
+                ] {
+                    let _ = plain;
+                }
+                for (plain, extra_plain) in [
+                    (&["-p"][..], false),
+                    (&["--plain"][..], false),
+                    (&["-pp"][..], true),
+                    (&["--plain", "--plain"][..], true),
+                ] {
+                    for paging_last in [false, true] {
+                        let mut args = vec!["bat".to_owned(), "test.txt".to_owned()];
+                        let paging_args = paging.map(|mode| format!("--paging={mode}"));
+                        if !paging_last {
+                            args.extend(paging_args.clone());
+                        }
+                        args.extend(plain.iter().map(|arg| (*arg).to_owned()));
+                        if paging_last {
+                            args.extend(paging_args);
+                        }
+
+                        let app = App {
+                            matches: clap_app::build_app(interactive_output)
+                                .get_matches_from(&args),
+                            interactive_output,
+                        };
+                        let inputs = app.inputs().unwrap();
+                        let config = app.config(&inputs).unwrap();
+                        let expected = if extra_plain && (!paging_last || paging.is_none()) {
+                            PagingMode::Never
+                        } else {
+                            match paging {
+                                Some("always") => PagingMode::Always,
+                                Some("never") => PagingMode::Never,
+                                _ if interactive_output => PagingMode::QuitIfOneScreen,
+                                _ => PagingMode::Never,
+                            }
+                        };
+                        assert_eq!(config.paging_mode, expected, "{args:?}");
+                        assert!(config.style_components.plain(), "{args:?}");
+                    }
+                }
+            }
+        }
+    }
+}
diff --git a/tests/integration_tests.rs b/tests/integration_tests.rs
--- a/tests/integration_tests.rs
+++ b/tests/integration_tests.rs
@@ -1021,2 +1021,29 @@
 #[test]
+#[serial]
+fn pager_plain_preserves_explicit_paging() {
+    mocked_pagers::with_mocked_versions_of_more_and_most_in_path(|| {
+        for (paging, expected) in [
+            ("--paging=never", "hello world\n"),
+            ("--paging=always", "pager-output\n"),
+        ] {
+            for plain in ["-p", "--plain"] {
+                for args in [[paging, plain], [plain, paging]] {
+                    bat()
+                        .env("PAGER", mocked_pagers::from("echo pager-output"))
+                        .args(args)
+                        .arg("--decorations=always")
+                        .arg("--color=never")
+                        .arg("test.txt")
+                        .assert()
+                        .success()
+                        .stdout(predicate::eq(expected).normalize());
+                }
+            }
+        }
+    });
+}
