 fn pager_failed_to_parse() {
PATCH
RUSTFLAGS=-Awarnings cargo test --package bat --bin bat paging_with_plain && RUSTFLAGS=-Awarnings cargo test --package bat --test integration_tests pager_plain_preserves_explicit_paging

